#!/usr/bin/env bash
# DD24 policy on the Pi. Run where ROS 2 + mavros are sourced (ros2 topic list shows /mavros/*).
#   bash dd24_bundle.sh bench   fake ToFs (down 0.0, sides 1.0) + policy node + monitor  (flight controller only)
#   bash dd24_bundle.sh fly     policy node + monitor, real ToFs                         (whole drone)
# Files go to ~/dd24. Evidence: ~/dd24/evidence.csv (monitor, 1 line/s) and ~/dd24/policy_log.csv (node, 20 Hz).
# Then arm and switch to OFFBOARD: the monitor's "sent" and "px4" columns should match and the motors move.
set -euo pipefail
MODE="${1:-bench}"
D="$HOME/dd24"
mkdir -p "$D"
cd "$D"
cat > policy_node.py <<'DD24_EOF'
"""Run the trained DD24 policy on the Pi: ROS 2 node, numpy only (no torch).

Plain script, run inside the container that has rclpy + mavros_msgs:
    python3 policy_node.py --policy dd24_oracle_wallmap.npz --height 0.5 \\
        --down_topic ... --front_topic ... --left_topic ... --right_topic ...

Inputs (latest message of each, held, with its age = now - header.stamp):
  /mavros/imu/data                           orientation, angular_velocity, linear_acceleration
  --down_topic / --front_topic / --left_topic / --right_topic: the four ToFs. In the 10-25
                 logs the driver topic names do not match the sensors: right_tof reads the
                 floor (down) and bottom_tof the right side. Cover each sensor by hand
                 (props off) and check before flying. Readings of 999 (no return) are
                 ignored, as in training.
Output, 20 Hz (the policy's training rate), on /mavros/setpoint_raw/attitude:
  attitude policies (action_mode in the .npz): roll / pitch attitude quaternion with the
    current heading + yaw rate + thrust (roll / pitch rates ignored);
  rates policies: thrust + body rates (attitude ignored).

Policies with 30 inputs also get position error and velocity from the wall-map estimator
(oracle_core.WallMap): walls are the front / left / right readings of the last second
before OFFBOARD, origin = takeoff spot, x = the heading at takeoff.

The node always streams setpoints (PX4 needs them before it accepts OFFBOARD), but
they are thrust 0 until the drone is armed AND in OFFBOARD. Then it waits 1 s on
the floor, climbs at 0.3 m/s to --height and holds it until you take over.
Landing is not trained: switch the dashboard back to STABILIZED and land by hand
(or disarm).

It also cuts to thrust 0 (drone drops) if tilt > 45 deg, IMU older than 0.5 s,
down ToF older than 1 s, or the position estimate leaves --max_xy of the takeoff spot.
From <1 m in the net that is the safe failure.
"""
import argparse
import collections
import math
import time

import numpy as np
import rclpy
from mavros_msgs.msg import AttitudeTarget, State
from rclpy.node import Node
from rclpy.qos import qos_profile_sensor_data
from sensor_msgs.msg import Imu, Range

from oracle_core import FRD, Policy, Scripted, WallMap, attitude_quat_enu, observation, qmul, tilt_deg, yaw_of

RATE_HZ = 20.0
TARGET_SPEED_MPS = 0.3


def stamp_s(msg):
    return msg.header.stamp.sec + msg.header.stamp.nanosec * 1e-9


class PolicyNode(Node):
    def __init__(self, args):
        super().__init__("dd24_policy")
        self.args = args
        self.scripted = args.controller == "scripted"
        self.policy = Scripted(max_tilt_rad=math.radians(args.max_tilt_deg)) if self.scripted else Policy(args.policy, args.action)
        self.imu = None
        self.tofs = [None] * 4    # down, front, left, right
        self.side_hist = collections.deque()   # (time, front, left, right) readings, last 1 s
        self.armed_offboard = False
        self.t_start = None
        self.target = 0.0
        self.last_sp = np.zeros(4, np.float32)
        self.done = False
        self.wallmap = None
        self.q_yaw0_inv = np.array([1.0, 0, 0, 0])
        self.create_subscription(Imu, "/mavros/imu/data", self.on_imu, qos_profile_sensor_data)
        topics = [args.down_topic, args.front_topic, args.left_topic, args.right_topic]
        for i, topic in enumerate(topics):
            self.create_subscription(Range, topic, lambda m, i=i: self.on_tof(i, m), qos_profile_sensor_data)
        self.create_subscription(State, "/mavros/state", self.on_state, 10)
        self.pub = self.create_publisher(AttitudeTarget, "/mavros/setpoint_raw/attitude", 10)
        self.log = open(args.log, "w") if args.log else None
        if self.log:
            self.log.write("t,active,target,tof_down,tof_front,tof_left,tof_right,tof_age,imu_age,tilt_deg,"
                           "est_x,est_y,est_z,est_vx,est_vy,est_vz,thrust,roll,pitch,yaw_rate\n")
        self.create_timer(1.0 / RATE_HZ, self.tick)
        self.get_logger().info(f"{'scripted PID, max tilt ' + str(args.max_tilt_deg) + ' deg' if self.scripted else 'policy ' + args.policy} ({self.policy.action_mode}, {self.policy.n_obs} inputs"
                               f"{', wall-map estimator' if self.policy.oracle else ''}), "
                               f"ToF down/front/left/right {topics}, height {args.height} m (land by hand)")

    def on_imu(self, m):
        self.imu = m

    def on_tof(self, i, m):
        if 0.0 <= m.range < 100.0:  # 999 = no return: keep the previous reading, its age grows
            self.tofs[i] = m
            if i > 0 and None not in self.tofs[1:]:
                now = stamp_s(m)
                self.side_hist.append((now, *[t.range for t in self.tofs[1:]]))
                while self.side_hist and self.side_hist[0][0] < now - 1.0:
                    self.side_hist.popleft()

    def on_state(self, m):
        active = m.armed and m.mode == "OFFBOARD"
        if active and not self.armed_offboard:
            self.t_start, self.done = time.monotonic(), False
            if self.imu is not None:
                yaw0 = yaw_of(self.quat_enu())
                self.q_yaw0_inv = np.array([math.cos(yaw0 / 2), 0, 0, -math.sin(yaw0 / 2)])
            if self.policy.oracle:
                if self.side_hist:
                    walls = np.median(np.array([h[1:] for h in self.side_hist]), axis=0)
                    self.wallmap = WallMap(*walls, dt=1.0 / RATE_HZ, floor_h=self.args.floor_h)
                    self.get_logger().info(f"walls front {walls[0]:.2f} left {walls[1]:.2f} right {walls[2]:.2f} m")
                else:
                    self.wallmap = None
                    self.get_logger().error("no side ToF readings in the last second: not flying")
                    self.done = True
            self.get_logger().info("OFFBOARD + armed: flying profile")
        if not active and self.armed_offboard:
            self.get_logger().info("left OFFBOARD / disarmed: thrust 0")
        self.armed_offboard = active

    def quat_enu(self):
        q = self.imu.orientation
        return np.array([q.w, q.x, q.y, q.z])

    def goal(self, t):
        return 0.0 if t < 1.0 else self.args.height

    def tick(self):
        now = self.get_clock().now().nanoseconds * 1e-9
        sp = np.zeros(4, np.float32)
        tof, ages, tilt, est = [math.nan] * 4, [0.0] * 5, 0.0, (np.full(3, math.nan), np.full(3, math.nan))
        if self.armed_offboard and not self.done and self.imu is not None and None not in self.tofs:
            t = time.monotonic() - self.t_start
            step = TARGET_SPEED_MPS / RATE_HZ
            self.target += float(np.clip(self.goal(t) - self.target, -step, step))
            q_enu = self.quat_enu()
            quat = qmul(self.q_yaw0_inv, q_enu)            # takeoff frame, as in training
            quat = -quat if quat[0] < 0 else quat           # w >= 0, as the sim's quaternions near level
            w, a = self.imu.angular_velocity, self.imu.linear_acceleration
            gyro = np.array([w.x, w.y, w.z], np.float32) * FRD
            acc = np.array([a.x, a.y, a.z], np.float32) * FRD
            tof = np.array([m.range for m in self.tofs], np.float32)
            ages = np.array([now - stamp_s(m) for m in self.tofs] + [now - stamp_s(self.imu)])
            tilt = tilt_deg(q_enu)
            if self.policy.oracle:
                est = self.wallmap.step(tof, quat, acc, ages[0:4])
            obs = observation(tof, quat, gyro, acc, ages, self.last_sp, self.target, est if self.policy.oracle else None)
            far = self.policy.oracle and math.hypot(est[0][0], est[0][1]) > self.args.max_xy
            if tilt > 45.0 or ages[4] > 0.5 or ages[0] > 1.0 or far:
                self.get_logger().error(f"abort: tilt {tilt:.0f} deg, down ToF age {ages[0]:.2f} s, IMU age {ages[4]:.2f} s, "
                                        f"estimate xy ({est[0][0]:+.2f}, {est[0][1]:+.2f}) m")
                self.done = True
            else:
                sp = self.policy.command(est, quat, self.target) if self.scripted else self.policy.setpoint(self.policy(obs))
                sp[0] = min(sp[0], self.args.max_thrust)
        if not self.armed_offboard:
            self.target = 0.0
        self.last_sp = sp
        msg = AttitudeTarget()
        msg.header.stamp = self.get_clock().now().to_msg()
        msg.thrust = float(sp[0])
        if self.policy.action_mode == "attitude" and self.imu is not None:
            # Heading setpoint = current heading (as in training); the policy steers yaw by rate.
            q = attitude_quat_enu(float(sp[1]), float(sp[2]), yaw_of(self.quat_enu()))
            msg.type_mask = AttitudeTarget.IGNORE_ROLL_RATE | AttitudeTarget.IGNORE_PITCH_RATE
            msg.orientation.w, msg.orientation.x, msg.orientation.y, msg.orientation.z = (float(c) for c in q)
            msg.body_rate.z = float(-sp[3])                                            # FRD -> FLU
        else:
            msg.type_mask = AttitudeTarget.IGNORE_ATTITUDE
            msg.body_rate.x, msg.body_rate.y, msg.body_rate.z = float(sp[1]), float(-sp[2]), float(-sp[3])  # FRD -> FLU
        self.pub.publish(msg)
        if self.log:
            active = int(self.armed_offboard and not self.done)
            p, v = est
            self.log.write(f"{now:.3f},{active},{self.target:.3f}," + ",".join(f"{x:.3f}" for x in tof) +
                           f",{ages[0]:.3f},{ages[4]:.3f},{tilt:.1f}," + ",".join(f"{x:.3f}" for x in (*p, *v)) +
                           "," + ",".join(f"{x:.3f}" for x in sp) + "\n")


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--controller", choices=["policy", "scripted"], default="policy",
                   help="scripted: height PID on the down ToF + wall-map position hold, no RL")
    p.add_argument("--max_tilt_deg", type=float, default=5.0, help="scripted: tilt limit for position hold (0 = level, height only)")
    p.add_argument("--policy", default="dd24_oracle_wallmap.npz")
    p.add_argument("--action", choices=["rates", "attitude"], help="override the .npz action mode (older exports have none = rates)")
    p.add_argument("--down_topic", default="/noducksgiven/bottom_tof_driver_node/range")
    p.add_argument("--front_topic", default="/noducksgiven/front_tof_driver_node/range")
    p.add_argument("--left_topic", default="/noducksgiven/left_tof_driver_node/range")
    p.add_argument("--right_topic", default="/noducksgiven/right_tof_driver_node/range")
    p.add_argument("--height", type=float, default=0.5)
    p.add_argument("--max_thrust", type=float, default=0.65, help="hard cap on the thrust setpoint")
    p.add_argument("--max_xy", type=float, default=0.8, help="abort (thrust 0) when the xy estimate is this far from takeoff, m")
    p.add_argument("--floor_h", type=float, default=0.05, help="side ToF height above the floor when landed, m")
    p.add_argument("--log", default="policy_log.csv")
    args = p.parse_args()
    rclpy.init()
    node = PolicyNode(args)
    try:
        rclpy.spin(node)
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == "__main__":
    main()
DD24_EOF
cat > oracle_core.py <<'DD24_EOF'
"""Numpy-only pieces of the DD24 policy that policy_node.py and replay_check.py share:
the MLP, the observation, the wall-map estimator and the action -> setpoint mapping.
Each mirrors environments/drone_px4_env.py (cited per function) so the Pi feeds the
policy what it saw in training.

Frames: the sim's world is the takeoff frame (heading 0 at spawn), so the IMU quaternion
is rotated by the takeoff heading before it reaches the policy or the estimator.
mavros gives FLU body / ENU world; the policy uses FRD gyro / accel and wxyz quaternions.
"""
import math

import numpy as np

FRD = np.array([1.0, -1.0, -1.0], np.float32)
G = 9.81
AGE_CLIP_S = 1.0           # DronePX4EnvCfg.age_clip_s
SIDE_DEFAULT_M = 3.5       # held side ToF before its first return (side_tof_range_m[1])
DIRS_B = np.array([[0, 0, -1], [1, 0, 0], [0, 1, 0], [0, -1, 0]], np.float64)   # down, front, left, right (FLU)


def qmul(a, b):
    aw, ax, ay, az = a
    bw, bx, by, bz = b
    return np.array([aw * bw - ax * bx - ay * by - az * bz, aw * bx + ax * bw + ay * bz - az * by,
                     aw * by - ax * bz + ay * bw + az * bx, aw * bz + ax * by - ay * bx + az * bw])


def qrot(q, v):
    return qmul(qmul(q, np.r_[0.0, v]), q * np.array([1, -1, -1, -1]))[1:]


def yaw_of(q):
    w, x, y, z = q
    return math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z))


def tilt_deg(q):
    w, x, y, z = q
    return math.degrees(math.acos(max(-1.0, min(1.0, 1.0 - 2.0 * (x * x + y * y)))))


class Policy:
    """MLP from deploy/export_policy.py (ELU hidden layers, tanh output)."""

    def __init__(self, path, action_mode=None):
        z = np.load(path)
        self.layers = []
        i = 0
        while f"W{i}" in z:
            self.layers.append((z[f"W{i}"], z[f"b{i}"]))
            i += 1
        self.hover, self.thr_range, self.rate_scale = float(z["hover_thrust"]), float(z["thrust_range"]), z["rate_scale"]
        self.action_mode = action_mode or (str(z["action_mode"]) if "action_mode" in z else "rates")
        self.tilt_max = float(z["att_tilt_max_rad"]) if "att_tilt_max_rad" in z else 0.35
        self.n_obs = self.layers[0][0].shape[1]
        self.oracle = self.n_obs == 30          # 24 base + 6 oracle slots (set_policy_obs)
        assert self.n_obs in (24, 30), f"policy expects {self.n_obs} inputs: history / estimator obs not supported here"

    def __call__(self, obs):
        x = obs
        for k, (w, b) in enumerate(self.layers):
            x = w @ x + b
            if k < len(self.layers) - 1:
                x = np.where(x > 0, x, np.expm1(x))  # ELU
        return np.clip(np.tanh(x), -1.0, 1.0)

    def setpoint(self, a):
        """policy_to_ctbr + _pre_physics_step: [thrust, roll, pitch, yaw] where roll / pitch are
        FRD angles (rad) in attitude mode and FRD rates in rates mode; yaw is always a rate."""
        thrust = min(max(self.hover + self.thr_range * a[0], 0.0), 1.0)
        rates = a[1:4] * self.rate_scale
        if self.action_mode == "attitude":
            rates[0:2] = a[1:3] * self.tilt_max
        return np.r_[thrust, rates].astype(np.float32)


class WallMap:
    """DronePX4Env._estimate_wallmap for one drone. Walls: x+ at the front reading, y+ at the
    left, y- at the right, all taken on the floor before takeoff; no back wall (never seen).
    Rays start floor_h above the floor: on the real floor the drone sits ~0.3 deg off level and,
    from height 0, every side ray tilted down would count as a floor hit (the sim sits level)."""

    def __init__(self, front, left, right, dt=0.05, alpha=0.5, beta=0.15, floor_h=0.05):
        self.hi = (front, left)
        self.lo = (-1e3, -right)
        self.dt, self.alpha, self.beta, self.floor_h = dt, alpha, beta, floor_h
        self.p, self.v, self.fresh = np.zeros(3), np.zeros(3), True

    def step(self, tof, quat, accel_frd, tof_age):
        dt = self.dt
        a_w = qrot(quat, accel_frd * FRD) + np.array([0.0, 0.0, -G])
        if self.fresh:
            p, v = np.zeros(3), np.zeros(3)
        else:
            p, v = self.p + self.v * dt + 0.5 * a_w * dt * dt, self.v + a_w * dt
        dirs = [qrot(quat, d) for d in DIRS_B]
        ok = tof_age < 0.2
        meas = [None, None, None]
        dz = -dirs[0][2]
        if ok[0] and dz > 0.5:
            meas[2] = tof[0] * dz
        sx, sy = [], []
        for i in (1, 2, 3):
            if not ok[i]:
                continue
            d = dirs[i]
            wx = self.hi[0] if d[0] > 0 else self.lo[0]
            wy = self.hi[1] if d[1] > 0 else self.lo[1]
            tx = (wx - p[0]) / d[0] if abs(d[0]) > 1e-3 else 1e6
            ty = (wy - p[1]) / d[1] if abs(d[1]) > 1e-3 else 1e6
            tf = -(max(p[2], 0.0) + self.floor_h) / d[2] if d[2] < -1e-3 else 1e6
            if tx <= ty and tx < tf:
                sx.append(wx - tof[i] * d[0])
            elif ty < tx and ty < tf:
                sy.append(wy - tof[i] * d[1])
        if sx:
            meas[0] = sum(sx) / len(sx)
        if sy:
            meas[1] = sum(sy) / len(sy)
        al, be = (1.0, 0.0) if self.fresh else (self.alpha, self.beta)
        for i in range(3):
            if meas[i] is not None:
                r = meas[i] - p[i]
                p[i] += al * r
                v[i] += be / dt * r
        self.p, self.v, self.fresh = p, v, False
        return p, v


def observation(tof, quat, gyro_frd, accel_frd, ages, last_sp, target, est=None):
    """DronePX4Env._sensors (+ the oracle slots of _get_observations when est = (p, v))."""
    ages = np.clip(ages, 0.0, AGE_CLIP_S)
    parts = [tof, quat, gyro_frd, accel_frd, ages, last_sp, [target]]
    if est is not None:
        p, v = est
        parts += [[-p[0], -p[1], target - p[2]], v]
    return np.concatenate(parts).astype(np.float32)


def attitude_quat_enu(roll_frd, pitch_frd, yaw_enu):
    """DronePX4Env._attitude_to_rates' setpoint: yaw (current heading) * pitch * roll, as an
    ENU / FLU quaternion for mavros (FRD pitch about +y right = FLU pitch about -y)."""
    h = lambda a: (math.cos(a / 2), math.sin(a / 2))  # noqa: E731
    cz, sz = h(yaw_enu)
    cy, sy = h(-pitch_frd)
    cx, sx = h(roll_frd)
    return qmul(qmul(np.array([cz, 0, 0, sz]), np.array([cy, 0, sy, 0])), np.array([cx, sx, 0, 0]))


class Scripted:
    """play_px4.py's reference commander on the wall-map estimate instead of ground truth:
    height PID on the down ToF, position PD -> tilt (clipped to max_tilt), attitude setpoints."""
    action_mode, oracle, n_obs = "attitude", True, 0

    def __init__(self, hover=0.47, max_tilt_rad=math.radians(5.0)):
        self.hover, self.max_tilt, self.z_int = hover, max_tilt_rad, 0.0

    def command(self, est, quat, target):
        p, v = est
        if target <= 0.0:
            self.z_int = 0.0
            return np.zeros(4, np.float32)
        z_err = target - p[2]
        if abs(z_err) < 0.15:            # no windup on the climb
            self.z_int += z_err * 0.02
        thrust = min(max(self.hover + 0.12 * z_err - 0.16 * v[2] + 0.08 * self.z_int, 0.0), 1.0)
        ax, ay = 1.5 * -p[0] - 2.0 * v[0], 1.5 * -p[1] - 2.0 * v[1]
        yaw = yaw_of(quat)
        c, s = math.cos(yaw), math.sin(yaw)
        fwd, left = c * ax + s * ay, -s * ax + c * ay
        pitch_flu = min(max(fwd / G, -self.max_tilt), self.max_tilt)    # +pitch tilts thrust forward
        roll_flu = min(max(-left / G, -self.max_tilt), self.max_tilt)   # -roll tilts thrust left
        return np.array([thrust, roll_flu, -pitch_flu, 0.0], np.float32)  # FRD roll, pitch
DD24_EOF
cat > fake_tof.py <<'DD24_EOF'
"""Stand-in ToFs for a bench test with only the flight controller attached: publishes
sensor_msgs/Range on the four topics policy_node.py reads, 20 Hz, fixed ranges.

    python3 fake_tof.py [--down 0.0] [--side 1.0]

--down 0.0 = sitting on the floor (the policy should command a climb once armed in OFFBOARD);
--down 0.5 = already at the hold height.
"""
import argparse

import rclpy
from rclpy.node import Node
from rclpy.qos import qos_profile_sensor_data
from sensor_msgs.msg import Range


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--down", type=float, default=0.0)
    p.add_argument("--side", type=float, default=1.0)
    p.add_argument("--prefix", default="/noducksgiven")
    args = p.parse_args()
    rclpy.init()
    node = Node("dd24_fake_tof")
    pubs = {k: node.create_publisher(Range, f"{args.prefix}/{k}_tof_driver_node/range", qos_profile_sensor_data)
            for k in ("bottom", "front", "left", "right")}
    ranges = {"bottom": args.down, "front": args.side, "left": args.side, "right": args.side}

    def tick():
        stamp = node.get_clock().now().to_msg()
        for k, pub in pubs.items():
            m = Range()
            m.header.stamp, m.header.frame_id = stamp, f"fake/{k}"
            m.min_range, m.max_range, m.range = 0.04, 3.6, ranges[k]
            pub.publish(m)

    node.create_timer(0.05, tick)
    node.get_logger().info(f"fake ToFs: down {args.down} m, sides {args.side} m on {args.prefix}/*_tof_driver_node/range")
    rclpy.spin(node)


if __name__ == "__main__":
    main()
DD24_EOF
cat > monitor.py <<'DD24_EOF'
"""Evidence that the policy is driving PX4: once a second, print and log what the node sends,
what PX4 says its attitude setpoint is, the motor outputs and the IMU.

    python3 monitor.py [--csv evidence.csv]

  sent   = /mavros/setpoint_raw/attitude         (policy_node.py -> mavros), rate and last value
  px4    = /mavros/setpoint_raw/target_attitude  (PX4's own attitude setpoint, echoed back):
           in OFFBOARD it should follow "sent"
  motors = /mavros/rc/out                        (PWM of the first 4 outputs)
"""
import argparse
import math
import time

import rclpy
from mavros_msgs.msg import AttitudeTarget, RCOut, State
from rclpy.node import Node
from rclpy.qos import qos_profile_sensor_data
from sensor_msgs.msg import Imu


def rp_deg(q):
    w, x, y, z = q.w, q.x, q.y, q.z
    return (math.degrees(math.atan2(2 * (w * x + y * z), 1 - 2 * (x * x + y * y))),
            math.degrees(math.asin(max(-1.0, min(1.0, 2 * (w * y - z * x))))))


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--csv", default="evidence.csv")
    args = p.parse_args()
    rclpy.init()
    node = Node("dd24_monitor")
    last = {"state": None, "sent": None, "px4": None, "rc": None, "imu": None}
    count = {k: 0 for k in last}

    def keep(k):
        def cb(m):
            last[k] = m
            count[k] += 1
        return cb

    node.create_subscription(State, "/mavros/state", keep("state"), qos_profile_sensor_data)
    node.create_subscription(AttitudeTarget, "/mavros/setpoint_raw/attitude", keep("sent"), qos_profile_sensor_data)
    node.create_subscription(AttitudeTarget, "/mavros/setpoint_raw/target_attitude", keep("px4"), qos_profile_sensor_data)
    node.create_subscription(RCOut, "/mavros/rc/out", keep("rc"), qos_profile_sensor_data)
    node.create_subscription(Imu, "/mavros/imu/data", keep("imu"), qos_profile_sensor_data)
    f = open(args.csv, "w")
    f.write("t,mode,armed,sent_hz,sent_thrust,sent_roll,sent_pitch,sent_yaw_rate,px4_hz,px4_thrust,px4_roll,px4_pitch,"
            "m1,m2,m3,m4,imu_hz,imu_roll,imu_pitch\n")
    t0 = time.monotonic()

    def report():
        dt = 1.0
        hz = {k: count[k] / dt for k in count}
        for k in count:
            count[k] = 0
        s, sent, px4, rc, imu = (last[k] for k in ("state", "sent", "px4", "rc", "imu"))
        mode, armed = (s.mode, int(s.armed)) if s else ("?", 0)
        st = (sent.thrust, *rp_deg(sent.orientation), -sent.body_rate.z) if sent else (math.nan,) * 4
        pt = (px4.thrust, *rp_deg(px4.orientation)) if px4 else (math.nan,) * 3
        m = list(rc.channels[:4]) if rc and len(rc.channels) >= 4 else [0] * 4
        ir = rp_deg(imu.orientation) if imu else (math.nan, math.nan)
        t = time.monotonic() - t0
        print(f"t={t:6.1f}s {mode:>10s} armed={armed} | sent {hz['sent']:4.1f}Hz thr {st[0]:.3f} roll {st[1]:+5.1f} pitch {st[2]:+5.1f} "
              f"yaw_rate {st[3]:+.2f} | px4 {hz['px4']:4.1f}Hz thr {pt[0]:.3f} roll {pt[1]:+5.1f} pitch {pt[2]:+5.1f} "
              f"| motors {m} | imu {hz['imu']:4.0f}Hz roll {ir[0]:+5.1f} pitch {ir[1]:+5.1f}", flush=True)
        f.write(f"{t:.1f},{mode},{armed},{hz['sent']:.1f}," + ",".join(f"{x:.3f}" for x in st) + f",{hz['px4']:.1f}," +
                ",".join(f"{x:.3f}" for x in pt) + "," + ",".join(str(x) for x in m) + f",{hz['imu']:.0f},{ir[0]:.2f},{ir[1]:.2f}\n")
        f.flush()

    node.create_timer(1.0, report)
    rclpy.spin(node)


if __name__ == "__main__":
    main()
DD24_EOF
